const horaSolicitadaInicio = $('Parsear clasificación').first().json.hora_inicio;
const horaSolicitadaFin = $('Parsear clasificación').first().json.hora_fin;

const toMinutes = (hora) => {
  const [h, m] = hora.split(':').map(Number);
  return h * 60 + m;
};

const inicioSolicitado = toMinutes(horaSolicitadaInicio);
const finSolicitado = toMinutes(horaSolicitadaFin);

let conflicto = false;
let reservaConflicto = null;

for (const item of $input.all()) {
  const reserva = item.json.fields;

  if (!reserva?.hora_inicio || !reserva?.hora_fin) continue;

  const inicioExistente = toMinutes(reserva.hora_inicio);
  const finExistente = toMinutes(reserva.hora_fin);

  if (
    inicioSolicitado < finExistente &&
    finSolicitado > inicioExistente
  ) {
    conflicto = true;
    reservaConflicto = reserva.id_reserva || null;
    break;
  }
}

return [
  {
    json: {
      disponible: !conflicto,
      conflicto,
      reserva_conflicto: reservaConflicto
    }
  }
];

let rawKeywords = $('Parsear clasificación').first().json.palabras_clave;

// Si viene como texto JSON, convertirlo a Array
if (typeof rawKeywords === 'string') {
  try {
    rawKeywords = JSON.parse(rawKeywords);
  } catch {
    rawKeywords = [];
  }
}

const keywords = Array.isArray(rawKeywords)
  ? rawKeywords
      .map(k => String(k).toLowerCase().trim())
      .filter(Boolean)
  : [];

const registros = $input.all();

let mejorMatch = null;
let mejorScore = 0;

for (const item of registros) {
  const f = item.json.fields ?? item.json;

  const categoria = String(f.categoria ?? '').toLowerCase();
  const tema = String(f.tema ?? '').toLowerCase();
  const contenido = String(f.contenido ?? '').toLowerCase();

  let score = 0;

  for (const keyword of keywords) {
    if (categoria.includes(keyword)) {
      score += 2;
    }

    if (tema.includes(keyword)) {
      score += 2;
    }

    if (contenido.includes(keyword)) {
      score += 1;
    }
  }

  if (score > mejorScore) {
    mejorScore = score;
    mejorMatch = f;
  }
}

const encontrado = mejorScore >= 2;

return [
  {
    json: {
      encontrado,
      score: mejorScore,
      respuesta: encontrado ? (mejorMatch?.contenido ?? null) : null,
      categoria: encontrado ? (mejorMatch?.categoria ?? null) : null,
      tema: encontrado ? (mejorMatch?.tema ?? null) : null,
      palabras_clave: keywords
    }
  }
];
